import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type Language = 'en' | 'hi' | 'bn';

export interface SoilData {
  nitrogen: string;
  phosphorus: string;
  potassium: string;
  ph: string;
  type: string;
}

export interface ClimateData {
  rainfall: string;
  temperature: string;
}

export interface LocationData {
  state: string;
  district: string;
}

export interface CropPredictionResult {
  bestCrops: string[];
  estimatedYield: string;
  suitabilityScore: 'Low' | 'Medium' | 'High';
  riskFactors: string[];
  improvementTips: string[];
}

export interface DiseaseDetectionResult {
  diseaseName: string;
  severity: string;
  treatment: string[];
  preventiveSteps: string[];
  advice: string;
}

export interface FarmReport {
  timestamp: string;
  location: LocationData;
  soil: SoilData;
  climate: ClimateData;
  prediction: CropPredictionResult;
}

import { GoogleGenAI, Type } from "@google/genai";
import { SoilData, ClimateData, LocationData, CropPredictionResult, DiseaseDetectionResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getCropPrediction = async (
  location: LocationData,
  soil: SoilData,
  climate: ClimateData
): Promise<CropPredictionResult> => {
  const prompt = `Act as an Indian agricultural expert. Based on the following data, predict the best crops for the farmer.
  Location: ${location.district}, ${location.state}
  Soil: Type=${soil.type}, pH=${soil.ph}, N=${soil.nitrogen}, P=${soil.phosphorus}, K=${soil.potassium}
  Climate: Avg Rainfall=${climate.rainfall}mm, Avg Temp=${climate.temperature}°C

  Provide results in JSON format matching the schema.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          bestCrops: { type: Type.ARRAY, items: { type: Type.STRING } },
          estimatedYield: { type: Type.STRING, description: "yield in tons per hectare" },
          suitabilityScore: { type: Type.STRING, enum: ["Low", "Medium", "High"] },
          riskFactors: { type: Type.ARRAY, items: { type: Type.STRING } },
          improvementTips: { type: Type.ARRAY, items: { type: Type.STRING } }
        },
        required: ["bestCrops", "estimatedYield", "suitabilityScore", "riskFactors", "improvementTips"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

export const detectCropDisease = async (
  imageData: string
): Promise<DiseaseDetectionResult> => {
  const prompt = `Identify the crop disease from this image and provide treatment and preventive advice. 
  Respond strictly in JSON format matching the schema.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { mimeType: "image/jpeg", data: imageData.split(',')[1] } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          diseaseName: { type: Type.STRING },
          severity: { type: Type.STRING },
          treatment: { type: Type.ARRAY, items: { type: Type.STRING } },
          preventiveSteps: { type: Type.ARRAY, items: { type: Type.STRING } },
          advice: { type: Type.STRING }
        },
        required: ["diseaseName", "severity", "treatment", "preventiveSteps", "advice"]
      }
    }
  });

  return JSON.parse(response.text || '{}');
};

import React from 'react';
import { Language } from '../types';

interface LanguageSelectorProps {
  currentLang: Language;
  onLanguageChange: (lang: Language) => void;
}

const LanguageSelector: React.FC<LanguageSelectorProps> = ({ currentLang, onLanguageChange }) => {
  const languages: { code: Language; label: string }[] = [
    { code: 'en', label: 'English' },
    { code: 'hi', label: 'हिंदी' },
    { code: 'bn', label: 'বাংলা' }
  ];

  return (
    <div className="flex gap-2">
      {languages.map((lang) => (
        <button
          key={lang.code}
          onClick={() => onLanguageChange(lang.code)}
          className={`px-3 py-1 rounded-full text-sm font-medium transition-all ${
            currentLang === lang.code
              ? 'bg-green-600 text-white shadow-md'
              : 'bg-white text-gray-700 hover:bg-gray-100 border border-gray-200'
          }`}
        >
          {lang.label}
        </button>
      ))}
    </div>
  );
};

export default LanguageSelector;

import React, { useEffect, useState } from 'react';

interface LoadingScreenProps {
  messages: string[];
}

const LoadingScreen: React.FC<LoadingScreenProps> = ({ messages }) => {
  const [currentStep, setCurrentStep] = useState(0);

  useEffect(() => {
    if (currentStep < messages.length - 1) {
      const timer = setTimeout(() => {
        setCurrentStep(prev => prev + 1);
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [currentStep, messages]);

  return (
    <div className="flex flex-col items-center justify-center p-12 bg-white rounded-2xl shadow-sm border border-green-100">
      <div className="relative w-16 h-16 mb-6">
        <div className="absolute top-0 left-0 w-full h-full border-4 border-green-100 rounded-full"></div>
        <div className="absolute top-0 left-0 w-full h-full border-4 border-green-600 rounded-full border-t-transparent animate-spin"></div>
      </div>
      <div className="space-y-3 w-full max-w-xs">
        {messages.map((msg, idx) => (
          <div key={idx} className="flex items-center gap-3">
            <div className={`w-2 h-2 rounded-full ${idx <= currentStep ? 'bg-green-600' : 'bg-gray-200'}`} />
            <p className={`text-sm ${idx === currentStep ? 'text-green-700 font-semibold' : idx < currentStep ? 'text-gray-400' : 'text-gray-300'}`}>
              {msg}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default LoadingScreen;

import React, { useState } from 'react';
import { TRANSLATIONS, INDIAN_STATES } from '../constants';
import { Language, LocationData, SoilData, ClimateData, CropPredictionResult } from '../types';
import { getCropPrediction } from '../services/gemini';
import LoadingScreen from './LoadingScreen';

interface CropPredictorProps {
  lang: Language;
}

const CropPredictor: React.FC<CropPredictorProps> = ({ lang }) => {
  const t = TRANSLATIONS[lang];
  const [loading, setLoading] = useState(false);
  const [location, setLocation] = useState<LocationData>({ state: '', district: '' });
  const [soil, setSoil] = useState<SoilData>({ nitrogen: '', phosphorus: '', potassium: '', ph: '', type: 'Alluvial' });
  const [climate, setClimate] = useState<ClimateData>({ rainfall: '', temperature: '' });
  const [result, setResult] = useState<CropPredictionResult | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await getCropPrediction(location, soil, climate);
      setResult(res);
    } catch (error) {
      alert("Error predicting crop. Please check your data.");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <LoadingScreen messages={[
        t.loading.fetching,
        t.loading.analyzingSoil,
        t.loading.processingRain,
        t.loading.estimatingYield,
        t.loading.generatingReport
      ]} />
    );
  }

  return (
    <div className="space-y-6">
      {!result ? (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <h2 className="text-2xl font-bold text-gray-800 mb-6">{t.nav.predictor}</h2>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Location */}
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.state}</label>
                <select
                  required
                  value={location.state}
                  onChange={(e) => setLocation({ ...location, state: e.target.value, district: '' })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                >
                  <option value="">{t.labels.state}</option>
                  {Object.keys(INDIAN_STATES).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.district}</label>
                <select
                  required
                  disabled={!location.state}
                  value={location.district}
                  onChange={(e) => setLocation({ ...location, district: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none disabled:opacity-50"
                >
                  <option value="">{t.labels.district}</option>
                  {location.state && INDIAN_STATES[location.state].map(d => <option key={d} value={d}>{d}</option>)}
                </select>
              </div>
            </div>

            {/* Soil */}
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.soilType}</label>
                <select
                  value={soil.type}
                  onChange={(e) => setSoil({ ...soil, type: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                >
                  <option value="Alluvial">Alluvial</option>
                  <option value="Black">Black (Regur)</option>
                  <option value="Red">Red</option>
                  <option value="Laterite">Laterite</option>
                  <option value="Arid">Arid / Sandy</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.ph}</label>
                  <input
                    type="number" step="0.1" required
                    value={soil.ph} onChange={(e) => setSoil({ ...soil, ph: e.target.value })}
                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                    placeholder="e.g. 6.5"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.nitrogen}</label>
                  <input
                    type="number" required
                    value={soil.nitrogen} onChange={(e) => setSoil({ ...soil, nitrogen: e.target.value })}
                    className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                    placeholder="mg/kg"
                  />
                </div>
              </div>
            </div>

            {/* More Soil & Climate */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.phosphorus}</label>
                <input
                  type="number" required
                  value={soil.phosphorus} onChange={(e) => setSoil({ ...soil, phosphorus: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                  placeholder="P"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.potassium}</label>
                <input
                  type="number" required
                  value={soil.potassium} onChange={(e) => setSoil({ ...soil, potassium: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                  placeholder="K"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.rainfall}</label>
                <input
                  type="number" required
                  value={climate.rainfall} onChange={(e) => setClimate({ ...climate, rainfall: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                  placeholder="mm"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">{t.labels.temperature}</label>
                <input
                  type="number" required
                  value={climate.temperature} onChange={(e) => setClimate({ ...climate, temperature: e.target.value })}
                  className="w-full p-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-green-500 outline-none"
                  placeholder="°C"
                />
              </div>
            </div>
          </div>

          <div className="mt-8 flex gap-4">
            <button
              type="submit"
              className="flex-1 bg-green-600 text-white font-bold py-4 rounded-xl hover:bg-green-700 transition-colors shadow-lg shadow-green-200"
            >
              {t.labels.predict}
            </button>
            <button
              type="button"
              onClick={() => { setLocation({ state: '', district: '' }); setSoil({ nitrogen: '', phosphorus: '', potassium: '', ph: '', type: 'Alluvial' }); setClimate({ rainfall: '', temperature: '' }); }}
              className="px-6 bg-white border border-gray-200 text-gray-600 font-medium py-4 rounded-xl hover:bg-gray-50 transition-colors"
            >
              {t.labels.reset}
            </button>
          </div>
        </form>
      ) : (
        <div className="bg-white p-8 rounded-2xl shadow-sm border border-green-100">
          <div className="flex justify-between items-start mb-8">
            <h2 className="text-3xl font-bold text-gray-900">{t.nav.report}</h2>
            <div className={`px-4 py-1 rounded-full text-sm font-bold ${
              result.suitabilityScore === 'High' ? 'bg-green-100 text-green-700' :
              result.suitabilityScore === 'Medium' ? 'bg-yellow-100 text-yellow-700' :
              'bg-red-100 text-red-700'
            }`}>
              {t.results.suitability}: {result.suitabilityScore}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
            <div className="bg-green-50 p-6 rounded-xl border border-green-100">
              <h3 className="text-lg font-bold text-green-800 mb-4 flex items-center gap-2">
                🌾 {t.results.recommended}
              </h3>
              <div className="flex flex-wrap gap-2">
                {result.bestCrops.map((crop, i) => (
                  <span key={i} className="bg-white px-4 py-2 rounded-lg border border-green-200 font-medium text-green-900">
                    {crop}
                  </span>
                ))}
              </div>
              <div className="mt-6">
                <p className="text-sm text-green-700 font-medium uppercase tracking-wider">{t.results.yield}</p>
                <p className="text-2xl font-bold text-green-900">{result.estimatedYield}</p>
              </div>
            </div>

            <div className="bg-amber-50 p-6 rounded-xl border border-amber-100">
              <h3 className="text-lg font-bold text-amber-800 mb-4 flex items-center gap-2">
                ⚠️ {t.results.risks}
              </h3>
              <ul className="space-y-2">
                {result.riskFactors.map((risk, i) => (
                  <li key={i} className="flex items-start gap-2 text-amber-900">
                    <span className="text-amber-500">•</span> {risk}
                  </li>
                ))}
              </ul>
            </div>
          </div>

          <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 mb-8">
            <h3 className="text-lg font-bold text-blue-800 mb-4 flex items-center gap-2">
              💡 {t.results.tips}
            </h3>
            <ul className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {result.improvementTips.map((tip, i) => (
                <li key={i} className="flex items-start gap-3 text-blue-900">
                  <div className="mt-1 w-5 h-5 bg-white rounded-full flex items-center justify-center text-xs font-bold shrink-0">{i+1}</div>
                  {tip}
                </li>
              ))}
            </ul>
          </div>

          <div className="flex gap-4">
            <button
              onClick={() => setResult(null)}
              className="flex-1 bg-gray-100 text-gray-700 font-bold py-4 rounded-xl hover:bg-gray-200 transition-colors"
            >
              ← Back
            </button>
            <button
              onClick={() => window.print()}
              className="flex-1 bg-green-600 text-white font-bold py-4 rounded-xl hover:bg-green-700 transition-colors shadow-lg"
            >
              {t.labels.download}
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default CropPredictor;

import React, { useState, useRef } from 'react';
import { TRANSLATIONS } from '../constants';
import { Language, DiseaseDetectionResult } from '../types';
import { detectCropDisease } from '../services/gemini';
import LoadingScreen from './LoadingScreen';

interface DiseaseDetectorProps {
  lang: Language;
}

const DiseaseDetector: React.FC<DiseaseDetectorProps> = ({ lang }) => {
  const t = TRANSLATIONS[lang];
  const [loading, setLoading] = useState(false);
  const [image, setImage] = useState<string | null>(null);
  const [result, setResult] = useState<DiseaseDetectionResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        setResult(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleDetect = async () => {
    if (!image) return;
    setLoading(true);
    try {
      const res = await detectCropDisease(image);
      setResult(res);
    } catch (error) {
      alert("Could not analyze image. Try a clearer photo.");
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <LoadingScreen messages={[
        t.loading.uploading,
        t.loading.analyzingImage,
        t.loading.detectingDisease,
        t.loading.preparingAdvice
      ]} />
    );
  }

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="bg-white p-8 rounded-2xl shadow-sm border border-gray-100">
        <h2 className="text-2xl font-bold text-gray-800 mb-6">{t.nav.disease}</h2>

        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1">
            <div 
              onClick={() => fileInputRef.current?.click()}
              className={`aspect-square rounded-2xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all ${
                image ? 'border-green-200' : 'border-gray-300 hover:border-green-400'
              }`}
            >
              {image ? (
                <img src={image} alt="Crop Leaf" className="w-full h-full object-cover rounded-2xl" />
              ) : (
                <div className="text-center p-6">
                  <div className="text-4xl mb-2">📸</div>
                  <p className="text-gray-500 font-medium">{t.labels.upload}</p>
                </div>
              )}
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/*" 
              onChange={handleImageUpload} 
            />

            <button
              onClick={handleDetect}
              disabled={!image}
              className="w-full mt-6 bg-green-600 text-white font-bold py-4 rounded-xl hover:bg-green-700 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {t.labels.detect}
            </button>
          </div>

          <div className="flex-1">
            {result ? (
              <div className="space-y-6">
                <div>
                  <h3 className="text-2xl font-bold text-red-600 mb-1">{result.diseaseName}</h3>
                  <p className="inline-block px-3 py-1 bg-red-100 text-red-700 text-xs font-bold rounded-full uppercase tracking-wider">
                    {t.results.severity}: {result.severity}
                  </p>
                </div>

                <div className="bg-gray-50 p-5 rounded-xl border border-gray-200">
                  <h4 className="font-bold text-gray-700 mb-2">{t.results.treatment}</h4>
                  <ul className="space-y-1">
                    {result.treatment.map((step, i) => (
                      <li key={i} className="text-sm text-gray-600 flex gap-2">
                        <span className="text-green-500 font-bold">✓</span> {step}
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="bg-gray-50 p-5 rounded-xl border border-gray-200">
                  <h4 className="font-bold text-gray-700 mb-2">{t.results.prevention}</h4>
                  <ul className="space-y-1">
                    {result.preventiveSteps.map((step, i) => (
                      <li key={i} className="text-sm text-gray-600 flex gap-2">
                        <span className="text-blue-500 font-bold">🛡️</span> {step}
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="p-4 bg-green-50 border border-green-100 rounded-xl">
                  <p className="text-sm text-green-800 italic">" {result.advice} "</p>
                </div>
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 text-center py-12">
                <div className="text-6xl mb-4 opacity-20">🍃</div>
                <p className="max-w-xs">Upload an image of the affected plant leaf to get a detailed diagnosis and solution.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default DiseaseDetector;

import React, { useState } from 'react';
import { Language } from './types';
import { TRANSLATIONS } from './constants';
import LanguageSelector from './components/LanguageSelector';
import CropPredictor from './components/CropPredictor';
import DiseaseDetector from './components/DiseaseDetector';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [activeTab, setActiveTab] = useState<'predictor' | 'disease'>('predictor');
  const t = TRANSLATIONS[lang];

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 py-4 flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-green-600 rounded-xl flex items-center justify-center text-white text-2xl">
              🌱
            </div>
            <div>
              <h1 className="text-2xl font-black text-green-900 tracking-tight">{t.title}</h1>
              <p className="text-xs text-green-600 font-medium">{t.tagline}</p>
            </div>
          </div>

          <div className="flex items-center gap-6">
            <LanguageSelector currentLang={lang} onLanguageChange={setLang} />
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="bg-white border-b border-slate-200">
        <div className="max-w-7xl mx-auto px-4 flex">
          <button
            onClick={() => setActiveTab('predictor')}
            className={`px-8 py-4 text-sm font-bold transition-all border-b-2 ${
              activeTab === 'predictor' ? 'border-green-600 text-green-600' : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            {t.nav.predictor}
          </button>
          <button
            onClick={() => setActiveTab('disease')}
            className={`px-8 py-4 text-sm font-bold transition-all border-b-2 ${
              activeTab === 'disease' ? 'border-green-600 text-green-600' : 'border-transparent text-gray-500 hover:text-gray-700'
            }`}
          >
            {t.nav.disease}
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-1 max-w-7xl mx-auto w-full p-4 md:p-8">
